import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Arrays;
import java.util.concurrent.ConcurrentHashMap;

public class PaymentProcessor {

    private static final int HEADER_SIZE = 16;
    private static final int MAX_PAYLOAD_SIZE = 4096;
    private static final int FIELD_SEPARATOR = 0x1F;

    private final ConcurrentHashMap<String, MerchantConfig> merchantConfigs;
    private final byte[] processingBuffer;
    private final int bufferCapacity;

    public PaymentProcessor() {
        String envCapacity = System.getenv("PAYMENT_BUFFER_CAPACITY");
        this.bufferCapacity = envCapacity != null ? Integer.parseInt(envCapacity) : 8192;
        this.processingBuffer = new byte[bufferCapacity];
        this.merchantConfigs = new ConcurrentHashMap<>();
        loadMerchantConfigs();
    }

    private void loadMerchantConfigs() {
        merchantConfigs.put("MERCHANT_A", new MerchantConfig("MERCHANT_A", 256, true));
        merchantConfigs.put("MERCHANT_B", new MerchantConfig("MERCHANT_B", 512, true));
        merchantConfigs.put("MERCHANT_C", new MerchantConfig("MERCHANT_C", 1024, false));
    }

    public PaymentResult processTransaction(byte[] rawMessage) {
        if (rawMessage == null || rawMessage.length < HEADER_SIZE) {
            return PaymentResult.error("Invalid message: too short");
        }

        TransactionHeader header = parseHeader(rawMessage);
        if (header == null) {
            return PaymentResult.error("Malformed header");
        }

        MerchantConfig config = merchantConfigs.get(header.merchantId);
        if (config == null) {
            return PaymentResult.error("Unknown merchant: " + header.merchantId);
        }

        return processWithConfig(rawMessage, header, config);
    }

    private PaymentResult processWithConfig(byte[] rawMessage, TransactionHeader header, MerchantConfig config) {
        int payloadOffset = HEADER_SIZE;
        int declaredPayloadLen = header.payloadLength;

        if (declaredPayloadLen > MAX_PAYLOAD_SIZE) {
            return PaymentResult.error("Payload exceeds maximum size");
        }

        int effectiveLen = computeEffectiveLength(declaredPayloadLen, config);

        if (effectiveLen > bufferCapacity) {
            return PaymentResult.error("Effective payload too large for buffer");
        }

        synchronized (processingBuffer) {
            Arrays.fill(processingBuffer, 0, effectiveLen, (byte) 0);
            copyPayloadToBuffer(rawMessage, payloadOffset, effectiveLen);
            return parseAndExecute(effectiveLen, config);
        }
    }

    private int computeEffectiveLength(int declaredLen, MerchantConfig config) {
        int paddingFactor = config.requiresPadding ? config.blockSize : 1;
        int alignedLen = ((declaredLen + paddingFactor - 1) / paddingFactor) * paddingFactor;
        int overhead = computeOverhead(config);
        long totalLong = (long) alignedLen + (long) overhead;
        if (totalLong > bufferCapacity || totalLong < 0) {
            return bufferCapacity + 1;
        }
        return (int) totalLong;
    }

    private int computeOverhead(MerchantConfig config) {
        String overheadEnv = System.getenv("MERCHANT_" + config.merchantId + "_OVERHEAD");
        if (overheadEnv != null) {
            int parsed = Integer.parseInt(overheadEnv);
            if (parsed < 0 || parsed > MAX_PAYLOAD_SIZE) {
                return config.requiresPadding ? config.blockSize : 32;
            }
            return parsed;
        }
        return config.requiresPadding ? config.blockSize : 32;
    }

    private void copyPayloadToBuffer(byte[] source, int offset, int length) {
        int available = source.length - offset;
        int toCopy = Math.min(available, length);
        System.arraycopy(source, offset, processingBuffer, 0, toCopy);
    }

    private PaymentResult parseAndExecute(int dataLen, MerchantConfig config) {
        int pos = 0;
        StringBuilder txnData = new StringBuilder();

        while (pos < dataLen) {
            int fieldEnd = findFieldEnd(pos, dataLen);
            byte[] fieldBytes = Arrays.copyOfRange(processingBuffer, pos, fieldEnd);
            txnData.append(new String(fieldBytes)).append("|");
            pos = fieldEnd + 1;
        }

        return PaymentResult.success(txnData.toString());
    }

    private int findFieldEnd(int start, int limit) {
        for (int i = start; i < limit; i++) {
            if (processingBuffer[i] == FIELD_SEPARATOR || processingBuffer[i] == 0) {
                return i;
            }
        }
        return limit;
    }

    private TransactionHeader parseHeader(byte[] raw) {
        try {
            ByteBuffer buf = ByteBuffer.wrap(raw, 0, HEADER_SIZE);
            buf.order(ByteOrder.BIG_ENDIAN);
            int version = buf.getShort() & 0xFFFF;
            if (version != 1 && version != 2) return null;

            int merchantCode = buf.getShort() & 0xFFFF;
            String merchantId = resolveMerchant(merchantCode);
            if (merchantId == null) return null;

            int payloadLength = buf.getInt();
            if (payloadLength < 0) return null;
            long timestamp = buf.getLong();

            return new TransactionHeader(version, merchantId, payloadLength, timestamp);
        } catch (Exception e) {
            return null;
        }
    }

    private String resolveMerchant(int code) {
        switch (code) {
            case 0x0001: return "MERCHANT_A";
            case 0x0002: return "MERCHANT_B";
            case 0x0003: return "MERCHANT_C";
            default: return null;
        }
    }

    static class TransactionHeader {
        final int version;
        final String merchantId;
        final int payloadLength;
        final long timestamp;

        TransactionHeader(int version, String merchantId, int payloadLength, long timestamp) {
            this.version = version;
            this.merchantId = merchantId;
            this.payloadLength = payloadLength;
            this.timestamp = timestamp;
        }
    }

    static class MerchantConfig {
        final String merchantId;
        final int blockSize;
        final boolean requiresPadding;

        MerchantConfig(String merchantId, int blockSize, boolean requiresPadding) {
            this.merchantId = merchantId;
            this.blockSize = blockSize;
            this.requiresPadding = requiresPadding;
        }
    }

    static class PaymentResult {
        final boolean success;
        final String message;

        PaymentResult(boolean success, String message) {
            this.success = success;
            this.message = message;
        }

        static PaymentResult success(String data) { return new PaymentResult(true, data); }
        static PaymentResult error(String msg) { return new PaymentResult(false, msg); }
    }
}
